const record = $('Validar Agendamento Salvo').item.json;
const labels = {"endolaser":"Endolaser","botox":"Toxina Botulínica (Botox)","consulta":"Consulta","preenchimento":"Preenchimento Facial e Labial","skin-booster":"Skin Booster","limpeza-de-pele-profunda":"Limpeza de Pele Profunda","acompanhamento-pos-operatorio":"Acompanhamento Pós-operatório","bioestimulador-de-colageno":"Bioestimulador de Colágeno","estimulador-de-colageno":"Estimulador de Colágeno","microagulhamento":"Microagulhamento","massagem-modeladora":"Massagem Modeladora","drenagem-linfatica":"Drenagem Linfática","massagem-relaxante":"Massagem Relaxante","massagem-pedras-quentes":"Massagem com Pedras Quentes","peeling-quimico":"Peeling Químico","tratamento-cicatriz":"Tratamento de Cicatriz","remocao-verrugas":"Remoção de Verrugas a Laser","remocao-queloide":"Remoção de Queloide","remocao-xantelasma":"Remoção de Xantelasma","reposicao-vitaminas":"Protocolos de Reposição de Vitaminas","profilaxia":"Profilaxia","clareamento":"Clareamento","protese":"Prótese","extracao":"Extração","restauracao":"Restauração","implante":"Implante","lente-de-contato":"Lente de contato","lifting-facial":"Lifting facial","cervicoplastia":"Cervicoplastia","blefaroplastia":"Blefaroplastia","ortomodelacao":"Ortomodelação","ortoplastia":"Ortoplastia","rinomodelacao":"Rinomodelação","coworking":"Coworking Beautes","coworking-odontologico":"Coworking Odontológico","coworking-procedimentos":"Coworking Sala de Procedimentos"};
const tag = String(record.service_tag || record.service || '');
const slug = tag.startsWith('serviço:') ? tag.slice('serviço:'.length) : '';
const instant = new Date(record.data_agendamento);
if (!Number.isFinite(instant.getTime())) throw new Error('Data do agendamento salvo é inválida.');
const fmt = (options) => new Intl.DateTimeFormat('pt-BR', { timeZone: 'America/Sao_Paulo', ...options }).format(instant);
const time = fmt({ hour: '2-digit', minute: '2-digit', hourCycle: 'h23' });
return { json: {
  external_message_id: record.external_message_id,
  remote_jid: record.remote_jid,
  service_tag: tag,
  tenant_slug: record.tenant_slug || 'beautes',
  data_agendamento: record.data_agendamento,
  alert_service: labels[slug] || slug.replace(/-/g, ' '),
  alert_weekday: fmt({ weekday: 'long' }),
  alert_date: fmt({ day: '2-digit', month: '2-digit' }),
  alert_time: time.endsWith(':00') ? time.slice(0, 2) + 'h' : time.replace(':', 'h')
} };

const base = $('Preparar Mensagem Confirmação').item.json;
let state = {};
try { state = typeof $json.booking_state_raw === 'string' && $json.booking_state_raw ? JSON.parse($json.booking_state_raw) : (($json.booking_state_raw && typeof $json.booking_state_raw === 'object') ? $json.booking_state_raw : {}); } catch (_) { state = {}; }
if (!state || typeof state !== 'object' || Array.isArray(state)) state = {};
// Só marca como confirmado pela equipe se o estado da conversa ainda aponta exatamente para o horário que a atendente validou.
if (state.scheduled_at && Date.parse(state.scheduled_at) === Date.parse(base.data_agendamento) && state.service_tag === base.service_tag) {
  state.updated_at = new Date().toISOString();
  state.system_confirmed = true;
  state.confirmed_scheduled_at = state.scheduled_at;
}
return { json: { ...base, booking_state: state } };

const body = $('POST Configurar Agenda').item.json.body || {};
const action = String(body.action || 'get').toLowerCase();
const validDays = ['segunda', 'terca', 'quarta', 'quinta', 'sexta'];
const rawDay = String(body.dia_aberto || 'segunda').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
const dia_aberto = validDays.includes(rawDay) ? rawDay : 'segunda';
const isSet = action === 'set';
return { json: { action, isSet, dia_aberto, key: 'beautes:agenda:dia_aberto' } };

const body = $('POST Salvar Contato').item.json.body || {};
const action = String(body.action || '');
let phone = String(body.remote_jid || body.telefone || '').split('@')[0].replace(/\D/g, '');
if (phone.length === 10 || phone.length === 11) phone = '55' + phone;
if (!/^55\d{10,11}$/.test(phone)) throw new Error('Telefone brasileiro inválido.');
const remote_jid = phone + '@s.whatsapp.net';
let value;
if (action === 'cadastro') {
  const nome = String(body.nome || '').trim();
  if (!nome || nome.length > 120) throw new Error('Nome inválido.');
  value = { nome, telefone: phone, servico: String(body.servico || 'Não informado').trim().slice(0,120), status: 'Atendimento Inicial', data_solicitacao: new Date().toISOString() };
} else if (action === 'status') {
  const coluna_id = String(body.coluna_id || '');
  if (!['novos_leads','qualificacao','aguardando_validacao'].includes(coluna_id)) throw new Error('Use a confirmação de agendamento para fechar o atendimento.');
  value = { coluna_id };
} else if (action === 'assinatura') {
  const assinatura_url = String(body.assinatura_url || '');
  if (assinatura_url.length > 700000 || !/^data:image\/png;base64,[A-Za-z0-9+/]+={0,2}$/.test(assinatura_url)) throw new Error('Assinatura inválida.');
  value = { assinatura_url, contrato_assinado: true };
} else throw new Error('Ação inválida.');
return { json: { remote_jid, storage_key: 'beautes:panel:contact:' + remote_jid + ':' + action, storage_value: JSON.stringify({ remote_jid, action, value, updated_at: new Date().toISOString() }) } };

const rows = $items('Buscar Pendentes (View)').map(x => x.json).filter(x => x.remote_jid);
const map = new Map(rows.map(row => [row.remote_jid, { ...row }]));
const meta = Object.values($json).flatMap(raw => { try { const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw; return parsed?.remote_jid && parsed?.action && parsed?.value ? [parsed] : []; } catch (_) { return []; } });
for (const m of meta.filter(m => m.action === 'cadastro')) if (!map.has(m.remote_jid)) map.set(m.remote_jid, { ...m.value, remote_jid: m.remote_jid });
for (const m of meta) {
  const row = map.get(m.remote_jid); if (!row) continue;
  if (m.action === 'assinatura') Object.assign(row, m.value);
  if (m.action === 'status') {
    const newerMessage = row.data_solicitacao && m.updated_at && Date.parse(row.data_solicitacao) > Date.parse(m.updated_at);
    if (!newerMessage) row.coluna_id = m.value.coluna_id;
  }
}
for (const row of map.values()) if (/agendamento confirmado|agendado|fechado/i.test(row.status || row.stage || '')) row.coluna_id = 'fechado';
return { json: { records: [...map.values()].sort((a,b) => (Date.parse(b.data_solicitacao)||0) - (Date.parse(a.data_solicitacao)||0)) } };
